          <button
            key={choice}
            ref={choice === "Cancel" ? cancel : undefined}
            className={choice === "Save" || choice === "Save to Notes" ? "primary" : ""}
            onClick={() => done(choice)}
          >
            {choice}
          </button>
        ))}
      </div>
