[package]
name = "sidelit"
version = "0.7.0"
edition = "2021"
default-run = "sidelit"

[build-dependencies]
tauri-build = { version = "2", features = [] }

[dependencies]
tauri = { version = "2", features = [] }
tauri-plugin-single-instance = "2"
tauri-plugin-dialog = "2"
tauri-plugin-opener = "2"
serde = { version = "1", features = ["derive"] }
serde_json = "1"
notify-debouncer-full = "0.7"
sha2 = "0.10"
tempfile = "3"
base64 = "0.22"
libc = "0.2"
url = "2"
tauri-plugin-wdio-webdriver = { version = "1.5", optional = true }
tauri-plugin-updater = "2"
git2 = { version = "0.21", default-features = false, features = ["vendored-libgit2"] }

[target.'cfg(target_os = "macos")'.dependencies]
objc2 = "0.6"
objc2-app-kit = { version = "0.3.2", default-features = false, features = ["std", "NSApplication", "NSImage"] }
objc2-foundation = { version = "0.3.2", default-features = false, features = ["std", "NSData"] }

[features]
default = []
desktop-test = ["dep:tauri-plugin-wdio-webdriver"]

[dev-dependencies]
minisign-verify = "0.3"

[[example]]
name = "update-manifest"
test = true
